#!/usr/bin/env node
// Copy the canonical offline engine into the extension so it ships inside the .vsix.
//
// WHY A COPY AND NOT A SYMLINK OR A PACKAGE DEPENDENCY
// `vsce package` follows the filesystem literally: a symlink is packaged as a broken
// link, and the engine is a generated artifact rather than a published npm package.
// Copying at build time is the only form that survives into the installed extension.
//
// WHY IT MUST BE RE-RUN
// agent/denpex_canonical.mjs is regenerated by scripts/gen-canonical-offline-engine.mjs
// whenever pattern or contract behaviour changes. A stale copy here means VS Code users
// silently run an older engine than the website, the same class of drift that let the
// Marketplace serve a four-week-old build while the source-level parity gates passed.
// So this runs as part of `compile`, and it prints the engine version it copied.

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const here = __dirname;
const extRoot = path.resolve(here, '..');
// packages/denpex-vscode -> repo root
const repoRoot = path.resolve(extRoot, '..', '..');

const DEST_DIR = path.join(extRoot, 'engine');
const ASSETS = [
  {
    name: 'denpex_canonical.mjs',
    source: path.join(repoRoot, 'agent', 'denpex_canonical.mjs'),
    purpose: 'offline diagnosis engine',
  },
  {
    name: 'denpex_patterns.json',
    source: path.join(repoRoot, 'public', 'agent', 'denpex_patterns.json'),
    purpose: 'auditable pattern database',
  },
];

const missing = ASSETS.filter((asset) => !fs.existsSync(asset.source));
if (missing.length) {
  const allDestExist = ASSETS.every((asset) => fs.existsSync(path.join(DEST_DIR, asset.name)));
  if (allDestExist) {
    console.log('[bundle-engine] Using existing bundled engine artifacts in engine/.');
    process.exit(0);
  }
  console.error(
    `[bundle-engine] MISSING:\n${missing.map((asset) => `  ${asset.source} (${asset.purpose})`).join('\n')}\n` +
    `  Run \`npm run gen:canonical-offline\` from the repo root first.\n` +
    `  Refusing to build an extension whose offline diagnosis payload is incomplete.`,
  );
  process.exit(1);
}

fs.mkdirSync(DEST_DIR, { recursive: true });
for (const asset of ASSETS) {
  fs.copyFileSync(asset.source, path.join(DEST_DIR, asset.name));
}

// Prove the generated engine embeds the identity declared by the source of truth. A
// same-version stale bundle is possible, so the behavior fingerprint is the stronger
// half of this check.
const versionFile = path.join(repoRoot, 'worker', 'engine-version.ts');
if (!fs.existsSync(versionFile)) {
  console.log('[bundle-engine] Standalone build: pre-bundled engine verified.');
  process.exit(0);
}
const identitySource = fs.readFileSync(versionFile, 'utf8');
const version = identitySource.match(/export const ENGINE_VERSION\s*=\s*['"]([^'"]+)['"]/)?.[1];
const fingerprint = identitySource.match(/export const ENGINE_BEHAVIOR_FINGERPRINT\s*=\s*['"]([a-f0-9]{64})['"]/)?.[1];
if (!version || !fingerprint) {
  console.error('[bundle-engine] Could not read ENGINE_VERSION and ENGINE_BEHAVIOR_FINGERPRINT from worker/engine-version.ts.');
  process.exit(1);
}
const engineText = fs.readFileSync(path.join(DEST_DIR, 'denpex_canonical.mjs'), 'utf8');
if (!engineText.includes(version) || !engineText.includes(fingerprint)) {
  console.error(
    `[bundle-engine] STALE: denpex_canonical.mjs does not embed version=${version} and fingerprint=${fingerprint}.\n`
    + '  Run `npm run gen:canonical-offline` from the repo root before packaging the extension.',
  );
  process.exit(1);
}

for (const asset of ASSETS) {
  const dest = path.join(DEST_DIR, asset.name);
  const kb = Math.round(fs.statSync(dest).size / 1024);
  const hash = crypto.createHash('sha256').update(fs.readFileSync(dest)).digest('hex');
  const suffix = asset.name === 'denpex_canonical.mjs'
    ? `  engineVersion=${version}  fingerprint=${fingerprint}`
    : '';
  console.log(`[bundle-engine] engine/${asset.name}  ${kb} KB  sha256=${hash}${suffix}`);
}
